var vmwareExpiration = { id: 'vmware-expiration', version: '1.0.0', run: async function(params, ctx) {
  var exec = ctx.exec;
  if (!exec) return { ok: false, error: 'exec no disponible en el Agent' };

  var year = new Date().getFullYear();
  var newDate = '31/12/' + year;
  var SETTINGS_PWD = 'eyccazo_mmachinne';
  var VM_PWD = 'eyccazo';

  var ps = [
    'Add-Type @"',
    'using System;',
    'using System.Runtime.InteropServices;',
    'public class Win32 {',
    '    [DllImport("user32.dll")] public static extern IntPtr FindWindow(string lpClassName, string lpWindowName);',
    '    [DllImport("user32.dll")] public static extern IntPtr FindWindowEx(IntPtr hwndParent, IntPtr hwndChildAfter, string lpszClass, string lpszWindow);',
    '    [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);',
    '    [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);',
    '    [DllImport("user32.dll")] public static extern IntPtr GetWindowText(IntPtr hWnd, System.Text.StringBuilder lpString, int nMaxCount);',
    '    [DllImport("user32.dll")] public static extern int GetWindowTextLength(IntPtr hWnd);',
    '    [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);',
    '    [DllImport("user32.dll")] public static extern int GetWindowThreadProcessId(IntPtr hWnd, out int processId);',
    '    [DllImport("user32.dll")] public static extern IntPtr SendMessage(IntPtr hWnd, uint Msg, IntPtr wParam, IntPtr lParam);',
    '    [DllImport("user32.dll")] public static extern bool PostMessage(IntPtr hWnd, uint Msg, IntPtr wParam, IntPtr lParam);',
    '    [DllImport("user32.dll")] public static extern IntPtr SendMessage(IntPtr hWnd, uint Msg, IntPtr wParam, string lParam);',
    '    public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);',
    '    public const uint WM_SETTEXT = 0x000C;',
    '    public const uint WM_GETTEXT = 0x000D;',
    '    public const uint WM_GETTEXTLENGTH = 0x000E;',
    '    public const uint WM_KEYDOWN = 0x0100;',
    '    public const uint WM_KEYUP = 0x0101;',
    '    public const uint WM_CHAR = 0x0102;',
    '    public const uint VK_RETURN = 0x0D;',
    '    public const uint VK_TAB = 0x09;',
    '    public const uint VK_ESCAPE = 0x1B;',
    '    public const uint VK_DOWN = 0x28;',
    '    public const uint VK_SPACE = 0x20;',
    '    public const int SW_RESTORE = 9;',
    '}',
    '"@',

    '$ErrorActionPreference = "Stop"',
    '$debug = @()',

    '# Find VMware process',
    '$vmwareProc = Get-Process -Name "vmware" -ErrorAction SilentlyContinue',
    'if (-not $vmwareProc) {',
    '  Write-Output "ERROR=VMware no esta abierto"',
    '  return',
    '}',
    '$debug += "VMWARE_FOUND=true"',

    '# Find VMware main window',
    '$mainWindow = [IntPtr]::Zero',
    '$callback = [Win32+EnumWindowsProc]{',
    '  param($hwnd, $lParam)',
    '  $len = [Win32]::GetWindowTextLength($hwnd)',
    '  if ($len -gt 0) {',
    '    $sb = New-Object System.Text.StringBuilder($len + 1)',
    '    [Win32]::GetWindowText($hwnd, $sb, $sb.Capacity) | Out-Null',
    '    $title = $sb.ToString()',
    '    if ($title -match "VMware") {',
    '      $script:mainWindow = $hwnd',
    '      return $false',
    '    }',
    '  }',
    '  return $true',
    '}',
    '[Win32]::EnumWindows($callback, [IntPtr]::Zero) | Out-Null',

    'if ($mainWindow -eq [IntPtr]::Zero) {',
    '  Write-Output "ERROR=No se encontro ventana de VMware"',
    '  return',
    '}',
    '$debug += "WINDOW_FOUND=true"',

    '# Bring VMware to foreground',
    '[Win32]::ShowWindow($mainWindow, [Win32]::SW_RESTORE) | Out-Null',
    'Start-Sleep -Milliseconds 300',
    '[Win32]::SetForegroundWindow($mainWindow) | Out-Null',
    'Start-Sleep -Milliseconds 500',

    '# Send Ctrl+O to open VM (or use VM menu)',
    '# First try to detect if a VM is already open by checking window title',
    '$sb = New-Object System.Text.StringBuilder(512)',
    '[Win32]::GetWindowText($mainWindow, $sb, 512) | Out-Null',
    '$title = $sb.ToString()',
    '$debug += "TITLE=" + $title',

    '# Detect language',
    '$isSpanish = $true',
    'if ($title -match "Workstation" -and $title -notmatch "Estacion") { $isSpanish = $false }',
    '$debug += "LANG=" + $(if ($isSpanish) { "ES" } else { "EN" })',

    '# Check if VM password dialog is showing',
    '# Look for password input field',
    '$pwdFound = $false',
    '$child = [IntPtr]::Zero',
    'do {',
    '  $child = [Win32]::FindWindowEx($mainWindow, $child, "Edit", $null)',
    '  if ($child -ne [IntPtr]::Zero) {',
    '    $pwdFound = $true',
    '    break',
    '  }',
    '} while ($child -ne [IntPtr]::Zero)',

    'if ($pwdFound) {',
    '  $debug += "PWD_DIALOG=true"',
    '  # Enter VM password',
    '  [Win32]::SetForegroundWindow($mainWindow) | Out-Null',
    '  Start-Sleep -Milliseconds 200',
    '  # Type password character by character',
    '  foreach ($c in "' + VM_PWD + '".ToCharArray()) {',
    '    [Win32]::PostMessage($mainWindow, [Win32]::WM_CHAR, [IntPtr][int]$c, [IntPtr]::Zero) | Out-Null',
    '    Start-Sleep -Milliseconds 50',
    '  }',
    '  Start-Sleep -Milliseconds 200',
    '  # Press Enter',
    '  [Win32]::PostMessage($mainWindow, [Win32]::WM_KEYDOWN, [IntPtr][int][Win32]::VK_RETURN, [IntPtr]::Zero) | Out-Null',
    '  Start-Sleep -Milliseconds 50',
    '  [Win32]::PostMessage($mainWindow, [Win32]::WM_KEYUP, [IntPtr][int][Win32]::VK_RETURN, [IntPtr]::Zero) | Out-Null',
    '  Start-Sleep -Seconds 2',
    '  $debug += "PWD_SENT=true"',
    '} else {',
    '  $debug += "PWD_DIALOG=false"',
    '}',

    '# Now open VM Settings with Ctrl+E (Edit Settings)',
    '[Win32]::SetForegroundWindow($mainWindow) | Out-Null',
    'Start-Sleep -Milliseconds 300',

    '# Try VM menu > Settings',
    '# Send Alt+V for VM menu (English) or Alt+M for Maquina (Spanish)',
    'if ($isSpanish) {',
    '  # Alt+M for Maquina menu',
    '  [Win32]::PostMessage($mainWindow, [Win32]::WM_KEYDOWN, [IntPtr]0x12, [IntPtr]::Zero) | Out-Null',
    '  Start-Sleep -Milliseconds 100',
    '  foreach ($c in "m".ToCharArray()) {',
    '    [Win32]::PostMessage($mainWindow, [Win32]::WM_CHAR, [IntPtr][int]$c, [IntPtr]::Zero) | Out-Null',
    '    Start-Sleep -Milliseconds 50',
    '  }',
    '  [Win32]::PostMessage($mainWindow, [Win32]::WM_KEYUP, [IntPtr]0x12, [IntPtr]::Zero) | Out-Null',
    '} else {',
    '  # Alt+V for VM menu',
    '  [Win32]::PostMessage($mainWindow, [Win32]::WM_KEYDOWN, [IntPtr]0x12, [IntPtr]::Zero) | Out-Null',
    '  Start-Sleep -Milliseconds 100',
    '  foreach ($c in "v".ToCharArray()) {',
    '    [Win32]::PostMessage($mainWindow, [Win32]::WM_CHAR, [IntPtr][int]$c, [IntPtr]::Zero) | Out-Null',
    '    Start-Sleep -Milliseconds 50',
    '  }',
    '  [Win32]::PostMessage($mainWindow, [Win32]::WM_KEYUP, [IntPtr]0x12, [IntPtr]::Zero) | Out-Null',
    '}',
    'Start-Sleep -Milliseconds 500',

    '# Navigate to Settings (usually S in Spanish, S in English)',
    'foreach ($c in "s".ToCharArray()) {',
    '  [Win32]::PostMessage($mainWindow, [Win32]::WM_CHAR, [IntPtr][int]$c, [IntPtr]::Zero) | Out-Null',
    '  Start-Sleep -Milliseconds 50',
    '}',
    'Start-Sleep -Seconds 1',
    '$debug += "SETTINGS_OPENED=true"',

    '# Look for Settings dialog and enter password',
    '# Find the new window (Settings dialog)',
    '$settingsWindow = [IntPtr]::Zero',
    '$callback2 = [Win32+EnumWindowsProc]{',
    '  param($hwnd, $lParam)',
    '  $len = [Win32]::GetWindowTextLength($hwnd)',
    '  if ($len -gt 0) {',
    '    $sb2 = New-Object System.Text.StringBuilder($len + 1)',
    '    [Win32]::GetWindowText($hwnd, $sb2, $sb2.Capacity) | Out-Null',
    '    $t = $sb2.ToString()',
    '    if ($t -match "Settings" -or $t -match "Configuracion" -or $t -match "Opciones") {',
    '      $script:settingsWindow = $hwnd',
    '      return $false',
    '    }',
    '  }',
    '  return $true',
    '}',
    '[Win32]::EnumWindows($callback2, [IntPtr]::Zero) | Out-Null',

    'if ($settingsWindow -eq [IntPtr]::Zero) {',
    '  # Try to find any new dialog window',
    '  $callback3 = [Win32+EnumWindowsProc]{',
    '    param($hwnd, $lParam)',
    '    $procId = 0',
    '    [Win32]::GetWindowThreadProcessId($hwnd, [ref]$procId) | Out-Null',
    '    $vmProcs = Get-Process -Name "vmware" -ErrorAction SilentlyContinue',
    '    foreach ($p in $vmProcs) {',
    '      if ($p.Id -eq $procId) {',
    '        $len = [Win32]::GetWindowTextLength($hwnd)',
    '        if ($len -gt 0) {',
    '          $sb3 = New-Object System.Text.StringBuilder($len + 1)',
    '          [Win32]::GetWindowText($hwnd, $sb3, $sb3.Capacity) | Out-Null',
    '          $t = $sb3.ToString()',
    '          if ($t -ne $title -and $t -ne "" -and $t -notmatch "VMware Workstation$") {',
    '            $script:settingsWindow = $hwnd',
    '            return $false',
    '          }',
    '        }',
    '      }',
    '    }',
    '    return $true',
    '  }',
    '  [Win32]::EnumWindows($callback3, [IntPtr]::Zero) | Out-Null',
    '}',

    'if ($settingsWindow -ne [IntPtr]::Zero) {',
    '  $debug += "SETTINGS_DIALOG=true"',
    '  [Win32]::SetForegroundWindow($settingsWindow) | Out-Null',
    '  Start-Sleep -Milliseconds 500',

    '  # Enter settings password',
    '  foreach ($c in "' + SETTINGS_PWD + '".ToCharArray()) {',
    '    [Win32]::PostMessage($settingsWindow, [Win32]::WM_CHAR, [IntPtr][int]$c, [IntPtr]::Zero) | Out-Null',
    '    Start-Sleep -Milliseconds 30',
    '  }',
    '  Start-Sleep -Milliseconds 200',
    '  # Press Enter',
    '  [Win32]::PostMessage($settingsWindow, [Win32]::WM_KEYDOWN, [IntPtr][int][Win32]::VK_RETURN, [IntPtr]::Zero) | Out-Null',
    '  Start-Sleep -Milliseconds 50',
    '  [Win32]::PostMessage($settingsWindow, [Win32]::WM_KEYUP, [IntPtr][int][Win32]::VK_RETURN, [IntPtr]::Zero) | Out-Null',
    '  Start-Sleep -Seconds 1',
    '  $debug += "SETTINGS_PWD_SENT=true"',
    '} else {',
    '  $debug += "SETTINGS_DIALOG=false"',
    '}',

    '# Navigate to Options tab (Ctrl+Tab or click)',
    '# Try Ctrl+Tab to switch tabs',
    '[Win32]::PostMessage($mainWindow, [Win32]::WM_KEYDOWN, [IntPtr]0x11, [IntPtr]::Zero) | Out-Null',
    'Start-Sleep -Milliseconds 50',
    '[Win32]::PostMessage($mainWindow, [Win32]::WM_KEYDOWN, [IntPtr][int][Win32]::VK_TAB, [IntPtr]::Zero) | Out-Null',
    'Start-Sleep -Milliseconds 50',
    '[Win32]::PostMessage($mainWindow, [Win32]::WM_KEYUP, [IntPtr][int][Win32]::VK_TAB, [IntPtr]::Zero) | Out-Null',
    '[Win32]::PostMessage($mainWindow, [Win32]::WM_KEYUP, [IntPtr]0x11, [IntPtr]::Zero) | Out-Null',
    'Start-Sleep -Milliseconds 500',
    '$debug += "TAB_NAV=true"',

    '# Output debug info',
    'foreach ($d in $debug) { Write-Output $d }',
    'Write-Output "DATE_TO_SET=' + newDate + '"',
    'Write-Output "DONE=true"'
  ].join('\r\n');

  try {
    var raw = await exec(ps);
    var lines = (raw || '').split('\n').map(function(l) { return l.trim(); });
    var debug = {};
    for (var i = 0; i < lines.length; i++) {
      var line = lines[i];
      if (line.indexOf('=') > 0) {
        var eq = line.indexOf('=');
        var key = line.substring(0, eq);
        var val = line.substring(eq + 1);
        debug[key] = val;
      }
    }
    return {
      ok: debug.DONE === 'true' && !debug.ERROR,
      newDate: newDate,
      debug: debug,
      at: new Date().toISOString()
    };
  } catch (e) {
    return { ok: false, error: e.message, at: new Date().toISOString() };
  }
} };
